--
-- Table structure for table `tamilnadu_constituencies`
--

DROP TABLE IF EXISTS `tamilnadu_constituencies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tamilnadu_constituencies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `election_id` int NOT NULL,
  `district_id` int NOT NULL,
  `ac_no` int NOT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_electors` int DEFAULT NULL,
  `male_electors` int DEFAULT NULL,
  `female_electors` int DEFAULT NULL,
  `third_gender_electors` int DEFAULT NULL,
  `total_votes_polled` int DEFAULT NULL,
  `turnout_pct` decimal(5,2) DEFAULT NULL,
  `winning_margin` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `election_id` (`election_id`,`ac_no`),
  KEY `district_id` (`district_id`),
  KEY `ix_tamilnadu_constituencies_id` (`id`),
  CONSTRAINT `tamilnadu_constituencies_ibfk_1` FOREIGN KEY (`election_id`) REFERENCES `tamilnadu_elections` (`id`),
  CONSTRAINT `tamilnadu_constituencies_ibfk_2` FOREIGN KEY (`district_id`) REFERENCES `tamilnadu_districts` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=937 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

