  `election_id` int NOT NULL,
  `constituency_id` int NOT NULL,
  `party_id` int DEFAULT NULL,
  `name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `age` int DEFAULT NULL,
  `position` int DEFAULT NULL,
  `votes_general` int DEFAULT NULL,
  `votes_postal` int DEFAULT NULL,
  `votes_total` int DEFAULT NULL,
  `vote_pct` float DEFAULT NULL,
  `is_nota` tinyint(1) DEFAULT NULL,
  `education` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occupation` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `declared_assets` float DEFAULT NULL,
  `liabilities` float DEFAULT NULL,
  `criminal_cases` int DEFAULT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `election_id` (`election_id`),
  KEY `constituency_id` (`constituency_id`),
  KEY `party_id` (`party_id`),
  KEY `ix_uk_candidates_id` (`id`),
  CONSTRAINT `uk_candidates_ibfk_1` FOREIGN KEY (`election_id`) REFERENCES `uk_elections` (`id`),
  CONSTRAINT `uk_candidates_ibfk_2` FOREIGN KEY (`constituency_id`) REFERENCES `uk_constituencies` (`id`),
  CONSTRAINT `uk_candidates_ibfk_3` FOREIGN KEY (`party_id`) REFERENCES `uk_parties` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13097 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
