--
-- Table structure for table `westbengal_candidates`
--

DROP TABLE IF EXISTS `westbengal_candidates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `westbengal_candidates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `election_id` int NOT NULL,
  `constituency_id` int NOT NULL,
  `party_id` int DEFAULT NULL,
  `name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `age` int DEFAULT NULL,
  `position` int DEFAULT NULL,
  `votes_general` int DEFAULT NULL,
  `votes_postal` int DEFAULT NULL,
  `votes_total` int DEFAULT NULL,
  `vote_pct` decimal(5,2) DEFAULT NULL,
  `is_nota` tinyint(1) DEFAULT NULL,
  `education` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occupation` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `declared_assets` bigint DEFAULT NULL,
  `liabilities` bigint DEFAULT NULL,
  `criminal_cases` int DEFAULT NULL,
  `image_url` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `election_id` (`election_id`),
  KEY `constituency_id` (`constituency_id`),
  KEY `party_id` (`party_id`),
  KEY `ix_westbengal_candidates_id` (`id`),
  CONSTRAINT `westbengal_candidates_ibfk_1` FOREIGN KEY (`election_id`) REFERENCES `westbengal_elections` (`id`),
  CONSTRAINT `westbengal_candidates_ibfk_2` FOREIGN KEY (`constituency_id`) REFERENCES `westbengal_constituencies` (`id`),
  CONSTRAINT `westbengal_candidates_ibfk_3` FOREIGN KEY (`party_id`) REFERENCES `westbengal_parties` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9232 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `westbengal_candidates`
--

